arguments.command:
cd /tmp/vally-eval-trial-Bt7R15 && B=.copilot-tracking/skraft-plans/pricing && D=2026-10-10 && mkdir -p $B/features $B/details/$D $B/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $B/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver and Gold (AC-1 to AC-4 of ac.md). Values copied verbatim.
  # NOT DECIDED: Platinum. The business has not agreed a reduction, so no scenario
  # and no expected value exist for it. Do not add one until DISCUSS supplies an example.
  # OPEN QUESTION (AC-4): see test-plan-discount.md — title says "in the customer's favour"
  # but the expected 7 cents charged leaves the customer with no reduction.

  @happy-path @smoke
  Scenario: Returning Bronze customer is charged 9500 cents for a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Returning Silver customer is charged 9000 cents for a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Returning Gold customer is charged 8500 cents for a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Returning Bronze customer with a 7 cent basket is charged 7 cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Returning Bronze customer is charged 9500 cents for a 10000 cent basket
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_subtotal_less_the_tier_reduction(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
git rev-parse HEAD; dotnet --version; dotnet test --nologo --no-restore --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -25

